import{_ as e,o as l,c as r,a2 as o}from"./chunks/framework.Crpw6aS5.js";const g=JSON.parse('{"title":"三大投资类别体系 Partnership Investment Method","description":"巴菲特合伙基金时期的核心投资框架：低估普通股/套利/控股/相对低估","frontmatter":{"title":"三大投资类别体系 Partnership Investment Method","description":"巴菲特合伙基金时期的核心投资框架：低估普通股/套利/控股/相对低估"},"headers":[],"relativePath":"02_concepts/partnership-method.md","filePath":"02_concepts/partnership-method.md"}'),a={name:"02_concepts/partnership-method.md"};function i(n,t,s,h,d,u){return l(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="三大投资类别体系-partnership-investment-method" tabindex="-1">三大投资类别体系 Partnership Investment Method <a class="header-anchor" href="#三大投资类别体系-partnership-investment-method" aria-label="Permalink to &quot;三大投资类别体系 Partnership Investment Method&quot;">​</a></h1><blockquote><p>1957-1969年，巴菲特运营合伙基金期间，形成了一套完整的投资方法论。这套框架后来演变为巴菲特选股标准的雏形。理解这14年的方法论，是理解后来巴菲特思想的基础。</p></blockquote><hr><h2 id="核心出处" tabindex="-1">核心出处 <a class="header-anchor" href="#核心出处" aria-label="Permalink to &quot;核心出处&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">年份</th><th style="text-align:left;">重点内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="/01_letters/1957年/翻译.html">1957年翻译</a></strong></td><td style="text-align:left;">首次提到&quot;低估类&quot;普通股投资</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1962年/翻译.html">1962年翻译</a></strong></td><td style="text-align:left;">正式提出三大投资类别体系</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1964年/翻译.html">1964年翻译</a></strong></td><td style="text-align:left;">体系深化，增加&quot;相对低估&quot;类别</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1969年/翻译.html">1969年翻译</a></strong></td><td style="text-align:left;">解散合伙基金，完整复盘14年方法论</td></tr></tbody></table><hr><h2 id="一、三大投资类别体系" tabindex="-1">一、三大投资类别体系 <a class="header-anchor" href="#一、三大投资类别体系" aria-label="Permalink to &quot;一、三大投资类别体系&quot;">​</a></h2><p>1962年，巴菲特在致合伙人信中首次系统阐述了他的投资分类体系：</p><h3 id="第一类-低估类普通股-generals" tabindex="-1">第一类：低估类普通股（Generals） <a class="header-anchor" href="#第一类-低估类普通股-generals" aria-label="Permalink to &quot;第一类：低估类普通股（Generals）&quot;">​</a></h3><p><strong>定义</strong>：市场价格低于内在价值（通常是有形资产清算价值）的普通股。这类股票没有时间表，也没有催化剂，但价格足够低，提供了安全边际。</p><p><strong>特点</strong>：</p><ul><li>通常没有分红，或分红很少</li><li>市场短期不看好，但长期有升值潜力</li><li>巴菲特寻找的是&quot;打折的好东西&quot;</li><li>持仓时间：通常3-5年</li></ul><p><strong>典型案例</strong>：</p><ul><li>1962年买入的桑伯恩地图公司（Sanborn Map），以大幅折价于净资产的价格买入，最终私有化</li><li>1964年购买的美国运通（虽然后来归入其他类别）</li></ul><p><strong>核心理念</strong>：</p><blockquote><p>&quot;低估类股票的价格迟早会回归价值，可能是因为业绩改善，可能是因为市场重新评估，可能只是因为估值修复。关键是：买的足够便宜，就有足够的安全边际。&quot;</p></blockquote><h3 id="第二类-套利类-workouts" tabindex="-1">第二类：套利类（Workouts） <a class="header-anchor" href="#第二类-套利类-workouts" aria-label="Permalink to &quot;第二类：套利类（Workouts）&quot;">​</a></h3><p><strong>定义</strong>：有具体时间表和催化剂的投资机会，通常涉及企业事件（并购、重组、分拆、清算），价格几乎与事件结果绑定，而非与整体市场相关。</p><p><strong>特点</strong>：</p><ul><li>持仓时间短（通常几周到几个月）</li><li>收益可预测，波动小</li><li>收益主要来自企业事件，而非市场整体表现</li><li>通常不需要考虑宏观环境</li></ul><p><strong>典型案例</strong>：</p><ul><li>1961-1964年参与的Rockwood巧克力公司清算</li><li>1964年的Chemway公司重组</li></ul><p><strong>核心理念</strong>：</p><blockquote><p>&quot;套利类投资的收益与市场无关。如果市场下跌10%，低估类可能跟着跌，但套利类通常还是按计划走。这是降低整体组合波动的有效方式。&quot;</p></blockquote><h3 id="第三类-控股类-controls" tabindex="-1">第三类：控股类（Controls） <a class="header-anchor" href="#第三类-控股类-controls" aria-label="Permalink to &quot;第三类：控股类（Controls）&quot;">​</a></h3><p><strong>定义</strong>：买入足够多的股份以获得控制权，然后通过推动企业价值实现（资产重组、管理改善、清算）来获利。</p><p><strong>特点</strong>：</p><ul><li>持仓时间长，可能永久持有</li><li>需要主动参与企业管理</li><li>收益来自企业价值创造，而非市场定价</li><li>1965年后逐渐成为主要投资方式（伯克希尔收购）</li></ul><p><strong>典型案例</strong>：</p><ul><li>1965年收购伯克希尔哈撒韦（最初是套利，最终成为控股）</li><li>Dempster抽水机制造公司</li></ul><p><strong>核心理念</strong>：</p><blockquote><p>&quot;当市场价格远低于企业价值时，光买股票等价格回归太慢。控股可以直接推动价值实现。&quot;</p></blockquote><h3 id="后期增加-第四类——相对低估-relatively-undervalued" tabindex="-1">后期增加：第四类——相对低估（Relatively Undervalued） <a class="header-anchor" href="#后期增加-第四类——相对低估-relatively-undervalued" aria-label="Permalink to &quot;后期增加：第四类——相对低估（Relatively Undervalued）&quot;">​</a></h3><p>1964年，巴菲特增加了一个新的类别：</p><p><strong>定义</strong>：相对于其他同类普通股，价格更便宜但质地相近的股票。常用于与道琼斯指数比较。</p><p><strong>特点</strong>：</p><ul><li>与市场有较高相关性</li><li>收益来自相对表现（跑赢道指）</li><li>需要持续监控和调仓</li><li>1965年后逐渐淡出</li></ul><hr><h2 id="二、三大类别在合伙基金时期的收益贡献" tabindex="-1">二、三大类别在合伙基金时期的收益贡献 <a class="header-anchor" href="#二、三大类别在合伙基金时期的收益贡献" aria-label="Permalink to &quot;二、三大类别在合伙基金时期的收益贡献&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>典型收益</th><th>风险特征</th></tr></thead><tbody><tr><td>低估类（Generals）</td><td>很高，但有时需要等待3-5年</td><td>中等，需要耐心</td></tr><tr><td>套利类（Workouts）</td><td>稳定，年化10-20%</td><td>较低，与市场无关</td></tr><tr><td>控股类（Controls）</td><td>视情况而定，可很高</td><td>需要主动管理</td></tr></tbody></table><p>1962-1969年，合伙基金的年化收益约30%（同期道指约8%），三大类别的组合贡献实现了这一成绩。</p><hr><h2 id="三、从合伙基金到伯克希尔的演变" tabindex="-1">三、从合伙基金到伯克希尔的演变 <a class="header-anchor" href="#三、从合伙基金到伯克希尔的演变" aria-label="Permalink to &quot;三、从合伙基金到伯克希尔的演变&quot;">​</a></h2><p>1969年解散合伙基金时，巴菲特解释了他为什么要改变方法：</p><blockquote><p>&quot;这个游戏（低估类普通股投资）不再适合我了。资金规模太大了——低估类需要耐心等待3-5年，需要在足够低的价格买入大量股票。当资金量达到一定规模时，这两个条件越来越难满足。&quot;</p></blockquote><p>这解释了为什么后来的伯克希尔更多采用：</p><ul><li><strong>控股收购</strong>（替代控股类）：通过完全控制来主动创造价值</li><li><strong>优质少数股权</strong>（改进低估类）：买入优秀企业并永久持有，不需要&quot;等待价值回归&quot;</li><li><strong>套利类减少</strong>：资金规模使套利机会的容量受限</li></ul><hr><h2 id="四、对后来投资哲学的影响" tabindex="-1">四、对后来投资哲学的影响 <a class="header-anchor" href="#四、对后来投资哲学的影响" aria-label="Permalink to &quot;四、对后来投资哲学的影响&quot;">​</a></h2><p>合伙基金时期的三大类别，对巴菲特后来的投资哲学产生了深远影响：</p><ol><li><strong>安全边际是根基</strong> — 所有三类投资都基于&quot;买的便宜&quot;的原则</li><li><strong>市场先生理论的应用</strong> — 低估类直接从市场价格与价值背离中获利</li><li><strong>能力圈原则</strong> — 巴菲特只在他能判断价值的领域投资</li><li><strong>长期主义萌芽</strong> — 低估类需要等待3-5年，这训练了他的耐心</li><li><strong>错误分类的风险</strong> — 如果把低估类误判为控股类，可能付出高昂代价</li></ol><hr><h2 id="五、合伙基金的清算与转型" tabindex="-1">五、合伙基金的清算与转型 <a class="header-anchor" href="#五、合伙基金的清算与转型" aria-label="Permalink to &quot;五、合伙基金的清算与转型&quot;">​</a></h2><p>1969年，巴菲特宣布解散合伙基金：</p><blockquote><p>&quot;在当前的市场环境下，我无法有效管理如此大规模的资金来获得超额回报。低估类普通股的机会越来越少，价格也越来越高。我不想为了投资而投资。&quot;</p></blockquote><p>清算方式：</p><ul><li>将伯克希尔股票分配给合伙人</li><li>将其他持仓以公允价值转让给合伙人</li><li>正式结束14年的合伙基金时代</li></ul><p>巴菲特在最后一封信中写道：</p><blockquote><p>&quot;这不是结束，而是新的开始。我们的目标是相同的：寻找被低估的优质企业，以合理的价格买入，然后让复利发挥作用。&quot;</p></blockquote><hr><h2 id="相关主题" tabindex="-1">相关主题 <a class="header-anchor" href="#相关主题" aria-label="Permalink to &quot;相关主题&quot;">​</a></h2><ul><li><a href="./safety-margin.html">安全边际 Safety Margin</a> — 买的便宜是所有三类投资的核心原则</li><li><a href="./intrinsic-value.html">内在价值 Intrinsic Value</a> — 判断价值是三类投资的基础</li><li><a href="./long-term.html">长期主义 Long-term</a> — 低估类需要等待，训练了巴菲特的耐心</li></ul>',62)])])}const c=e(a,[["render",i]]);export{g as __pageData,c as default};
